select t.g_id,t.g_id gId,t.name,t.m_id,t.m_id mId,t.description,t.p_id,t.p_id pId,t.status_cd,t.status_cd
statusCd,t.url,t.seq,t.is_show,t.is_show isShow
from m_menu t
where 1 =1

    and t.g_id= #{gId}


    and t.name= #{name}


    and t.m_id= #{mId}


    and t.description= #{description}


    and t.p_id= #{pId}


    and t.status_cd= #{statusCd}


    and t.url= #{url}


    and t.seq= #{seq}


    and t.is_show= #{isShow}

order by t.create_time desc

    limit #{page}, #{row}

