SELECT pp.*,'-1' AS pg_id,'' AS pg_name FROM p_privilege_user ppu,p_privilege pp WHERE ppu.`p_id` = pp.`p_id`
AND pp.`resource` = #{resource}
AND ppu.`privilege_flag` = '0' AND ppu.`user_id` = #{userId} AND ppu.`status_cd` = '0' AND pp.`status_cd` = '0' UNION SELECT pp.*,ppg.pg_id,ppg.name pg_name FROM p_privilege_user ppu,p_privilege_group ppg,p_privilege pp,p_privilege_rel ppr WHERE ppu.`p_id` = ppr.pg_id AND ppr.pg_id = ppg.pg_id AND ppr.p_id = pp.`p_id`
AND pp.`resource` = #{resource}
AND ppu.`privilege_flag` = '1' AND ppu.`user_id` = #{userId} AND ppu.`status_cd` = '0' AND pp.`status_cd` = '0' AND ppg.status_cd = '0' AND ppr.status_cd = '0'
